export function Wordmark({
  variant,
  height = 22,
}: {
  variant: "on-dark" | "on-light";
  height?: number;
}) {
  if (height < 18) return <AppIcon size={height} />;
  const fill = variant === "on-dark" ? "#f4f3ef" : "#1a1a1a";
  const width = height * (WORDMARK_W / WORDMARK_H);
  return (
    <svg
      role="img"
      aria-label={BRAND.name}
      xmlns="http://www.w3.org/2000/svg"
      width={width}
      height={height}
      viewBox="140 127 1052 266"
      className="block shrink-0"
    >
      <rect x="557.6" y="272.06" width="119.4" height="11.09" fill={fill} />
      <path d={WORDMARK_PATH} fill={fill} />
      <circle cx="676.99" cy="277.6" r="32.41" fill="#ff4a1c" stroke="var(--color-bg)" strokeWidth="12.79" paintOrder="stroke" />
    </svg>
  );
}

export function AppIcon({ size = 32 }: { size?: number }) {
  const raw = useId().replace(/:/g, "");
  const clipId = `zyxys-icon-${raw}`;
  return (
    <svg
      role="img"
      aria-label={BRAND.name}
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 1024 1024"
      className="block shrink-0"
    >
      <rect width="1024" height="1024" rx="229" fill="#1a1a1a" />
      <clipPath id={clipId}>
        <rect width="1024" height="1024" rx="229" />
      </clipPath>
      <g clipPath={`url(#${clipId})`}>
        <rect x="0" y="524.8" width="555.2" height="64" fill="#f4f3ef" />
        <path d={ICON_PATH} fill="#f4f3ef" />
        <circle cx="555.2" cy="556.8" r="112" fill="#ff4a1c" stroke="#1a1a1a" strokeWidth="40" paintOrder="stroke" />
      </g>
    </svg>
  );
}
